<div class="modal-overlay" id="editModal" style="display:none;"><div class="modal"><button class="close-btn" onclick="closeEdit()">✕</button><h3>Edit Plan</h3><form method="post"><input type="hidden" name="csrf_token" value="<?php echo $_SESSION['csrf_token']; ?>"><input type="hidden" name="edit_plan" value="1"><input type="hidden" name="plan_id" id="eId"><div class="form-grid"><div class="form-group"><label>Name</label><input type="text" name="name" id="eName" required></div><div class="form-group"><label>Volume</label><input type="number" name="volume" id="eVol" min="1"></div><div class="form-group"><label>Days</label><input type="number" name="days" id="eDays" min="1"></div><div class="form-group"><label>Price</label><input type="number" name="price" id="ePrice" min="1000"></div></div><div class="form-group"><label style="display:flex;align-items:center;gap:10px;"><input type="checkbox" name="is_multi" id="eIsMulti" value="1" onchange="document.getElementById('eCountrySelect').style.display=this.checked?'none':'block'" style="width:auto;accent-color:var(--t1);"> 🌍 Multi</label></div><div class="form-group" id="eCountrySelect"><label>Country</label><select name="location" id="eLoc"><?php foreach($servers as $s): ?><option value="<?php echo $s['location']; ?>"><?php echo $s['location_emoji']??'🌍'; ?> <?php echo $s['location_name']; ?></option><?php endforeach; ?></select></div><div class="form-group"><label><input type="checkbox" name="featured" id="eFeat" style="width:auto;"> Featured</label></div><div style="display:flex;gap:8px;justify-content:flex-end;"><button type="button" class="btn btn-outline" onclick="closeEdit()">Cancel</button><button type="submit" class="btn btn-primary">Save</button></div></form></div></div>
