<?php endif; ?>
<script>
function editPlan(id,name,loc,vol,days,price,feat,isMulti){document.getElementById('eId').value=id;document.getElementById('eName').value=name;document.getElementById('eLoc').value=loc;document.getElementById('eVol').value=vol;document.getElementById('eDays').value=days;document.getElementById('ePrice').value=price;document.getElementById('eFeat').checked=feat;document.getElementById('eIsMulti').checked=isMulti;document.getElementById('eCountrySelect').style.display=isMulti?'none':'block';document.getElementById('editModal').style.display='flex';}
function closeEdit(){document.getElementById('editModal').style.display='none';}
var em=document.getElementById('editModal');if(em)em.addEventListener('click',function(e){if(e.target===this)closeEdit();});
function rejectPayment(id){document.getElementById('rejectPendingId').value=id;document.getElementById('rejectModal').style.display='flex';}
var rm=document.getElementById('rejectModal');if(rm)rm.addEventListener('click',function(e){if(e.target===this)this.style.display='none';});
function addServerRow(){var flags=<?php echo json_encode($allFlags); ?>;var o='';for(var c in flags)o+='<option value="'+flags[c]+'">'+flags[c]+'</option>';var r=document.createElement('div');r.className='server-row';r.innerHTML='<select name="server_flag[]" class="flag-select">'+o+'</select><input type="text" name="server_name[]" placeholder="Name"><input type="text" name="server_code[]" placeholder="Code"><input type="text" name="server_inbounds[]" placeholder="Inbounds"><button type="button" class="btn btn-danger btn-xs" onclick="this.closest(\'.server-row\').remove()">X</button>';document.getElementById('serversContainer').appendChild(r);}
function addTestRow(){var opts='';<?php foreach($servers as $s): ?>opts+='<option value="<?php echo $s['location']; ?>"><?php echo $s['location_emoji']??'🌍'; ?> <?php echo $s['location_name']; ?></option>';<?php endforeach; ?>var r=document.createElement('div');r.className='test-row';r.innerHTML='<select name="test_server[]" style="flex:2">'+opts+'</select><input type="number" name="test_volume[]" value="1" min="0.1" step="0.1" style="flex:1"><select name="test_unit[]" style="flex:1"><option value="GB">GB</option><option value="MB">MB</option></select><input type="number" name="test_hours[]" value="2" min="1" style="flex:1"><label class="multi-check"><input type="checkbox" name="test_multi[]" value="1" onchange="this.checked?this.closest(\'.test-row\').querySelector(\'select\').disabled=true:this.closest(\'.test-row\').querySelector(\'select\').disabled=false" style="accent-color:var(--t1)"> All</label><button type="button" class="btn btn-danger btn-xs" onclick="this.closest(\'.test-row\').remove()">X</button>';document.getElementById('testsContainer').appendChild(r);}
setTimeout(function(){var a=document.getElementById('autoAlert');if(a)a.style.display='none';},3000);
</script>
